import{_ as t}from"./chunks/15-ai-agents.Ct28VXVn.js";import{_ as r,a as n}from"./chunks/15c-ai-agents-mobile.rtU5QDIE.js";import{_ as a,o,c as s,a3 as i}from"./chunks/framework.BGhsAJMQ.js";const m=JSON.parse('{"title":"AI Agents 编码代理","description":"","frontmatter":{},"headers":[],"relativePath":"zh/features/ai-agents.md","filePath":"zh/features/ai-agents.md","lastUpdated":1793985812000}'),g={name:"zh/features/ai-agents.md"};function l(d,e,A,c,p,h){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-agents-编码代理" tabindex="-1">AI Agents 编码代理 <a class="header-anchor" href="#ai-agents-编码代理" aria-label="Permalink to &quot;AI Agents 编码代理&quot;">​</a></h1><p>在选中的 Filebox Agent 上打开 <strong>AI Agents</strong>，列出编码代理窗口、读取输出、发送提示词、使用白名单按键作答。这是独立的后端集成，不是远程 shell，也不是只读预览。</p><p><img src="'+t+'" alt="桌面 AI Agents 列表与详情"></p><h2 id="启用与安装" tabindex="-1">启用与安装 <a class="header-anchor" href="#启用与安装" aria-label="Permalink to &quot;启用与安装&quot;">​</a></h2><p>在 <strong>Settings</strong>（Agent Settings）中打开 <strong>AI Agents</strong> 并选择后端。开关保存在该 Agent 上，跨浏览器共享。关闭只停止 Filebox 的控制与监测，不会停止后端或正在运行的编码代理。</p><ul><li><strong>Herdr</strong>：在 Agent 机器上安装 <a href="https://herdr.ink" target="_blank" rel="noreferrer">Herdr CLI</a>（已对照 v0.9.5）。让 Agent 进程的 PATH 能找到 <code>herdr</code>，或用 <code>FILEBOX_AGENT_HERDR</code> 指定可执行文件，再点 <strong>Check installation</strong>。</li><li><strong>hc (experimental)</strong>：接入以 <code>fb=&lt;名称&gt;</code> 或 <code>filebox=&lt;名称&gt;</code> 标签明确授权的本地运行中 herdr-core 终端。见 <a href="/filebox/zh/ops/agent#experimental-hc-backend">实验性 hc 配置</a>。两者都安装时，自动选择优先使用 Herdr。</li></ul><p><strong>Meet AI Agents</strong> 介绍功能；<strong>Set up AI Agents</strong> 说明未安装或已关闭的状态。<strong>AI agent backend is not running</strong> 表示已找到 CLI，但需在 Agent 机器上启动后端。</p><p>Agent 启动时的 <code>FILEBOX_AGENT_AI_AGENTS_ENABLED=0</code> / <code>1</code> 会覆盖并锁定开关；<code>FILEBOX_AGENT_AI_AGENTS_BACKEND</code> 锁定后端选择。移除对应环境变量并重启 Agent 后可恢复网页控制。</p><p><img src="'+r+'" alt="Agent Settings 中的 AI Agents 设置"></p><h2 id="窗口、输出与输入" tabindex="-1">窗口、输出与输入 <a class="header-anchor" href="#窗口、输出与输入" aria-label="Permalink to &quot;窗口、输出与输入&quot;">​</a></h2><ul><li>按名称、代理类型、工作目录或 pane ID 搜索窗口；后端支持状态检测时可按状态筛选。<strong>Draft</strong> 标出未发送输入。视图挂载期间各窗口保留各自草稿，提示词被拒绝时也不会丢失。</li><li>选择窗口读取输出。<strong>Refresh output</strong> 获取新快照；AI Agents 设置中可控制自动刷新。刷新不会滚动远端应用自身的对话记录。</li><li>在输入区发送提示词。Enter 换行，Ctrl / ⌘ + Enter 发送。中断发送后重试前先检查输出：取消等待不能撤回已接受的输入。</li><li>使用 Enter、Esc 和 Up/Down，或打开 <strong>Keys</strong>，搜索 pi、Claude Code、Codex 快捷键配置。自动检测会选择配置，也可手动纠正。打开 Keys 或切换配置不会发送按键。快捷键受白名单限制，不提供任意原始输入；上游支持及自定义键位可能不同。</li><li>需要输入的提醒要求 Filebox 页面保持打开。检测可能漏掉问题，关闭页面后不保证通知。</li></ul><p><img src="'+n+'" alt="手机 AI Agents"></p><h2 id="提示词审核" tabindex="-1">提示词审核 <a class="header-anchor" href="#提示词审核" aria-label="Permalink to &quot;提示词审核&quot;">​</a></h2><p>默认每条提示词先在 Hub 审核再发送。破坏性命令、永久删除、提取密钥会被阻止；正常数据分析与开发允许通过。审核器会看到提示词与窗口近期输出。</p><p>视图显示审核<strong>已开启及模型</strong>、<strong>已关闭</strong>或<strong>未配置</strong>（禁用提示词）。未配置或审核失败时拒绝发送，不会绕过审核。读取输出、状态与白名单按键仍可用；按键不经 LLM 审核。编码代理可以修改浏览 root 之外的文件，请谨慎操作。</p><p>审核仅由管理员在 Hub 配置，不能在浏览器中配置。见 <a href="/filebox/zh/guide/llm-review">提示词审核（AI Agents）</a>。</p>',16)])])}const I=a(g,[["render",l]]);export{m as __pageData,I as default};
